// DecodeError identifies and decodes a declared custom error.
func (c *DiesisPublicResolverBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("InvalidRoute()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidRouteError(raw)
	}
	if definition, err := c.customError("NotAuthorized()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotAuthorizedError(raw)
	}
	if definition, err := c.customError("OwnableInvalidOwner(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeOwnableInvalidOwnerError(raw)
	}
	if definition, err := c.customError("OwnableUnauthorizedAccount(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeOwnableUnauthorizedAccountError(raw)
	}
	if definition, err := c.customError("RecordTooLarge()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeRecordTooLargeError(raw)
	}
	if definition, err := c.customError("ResolverCallFailed()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeResolverCallFailedError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
